import sys

def solve():
    text = sys.stdin.readline().rstrip('\n')
    pattern = sys.stdin.readline().rstrip('\n')

    if not text and not pattern:
        print("YES")
        return
    if not text and pattern:
        print("YES" if all(c == '*' for c in pattern) else "NO")
        return
    if not pattern and text:
        print("NO")
        return

    # Simple DP approach
    m, n = len(text), len(pattern)
    # dp[i][j] = does text[0:i] match pattern[0:j]
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    # Handle patterns like a**, b***, etc.
    for j in range(1, n + 1):
        if pattern[j-1] == '*':
            dp[0][j] = dp[0][j-1]
        else:
            break

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if pattern[j-1] == '*':
                # * matches empty or some characters
                dp[i][j] = dp[i][j-1] or dp[i-1][j]
            elif pattern[j-1] == '?' or text[i-1] == pattern[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = False

    print("YES" if dp[m][n] else "NO")

solve()
